def repeated_string_match(a, b):
    text, count = a, 1
    while len(text) < len(b):
        text += a; count += 1
    if b in text:
        return count
    if b in text + a:
        return count + 1
    return -1

def repeated_string_match(a, b):
    pi, k = [0] * len(b), 0
    for i in range(1, len(b)):
        while k and b[i] != b[k]:
            k = pi[k - 1]
        if b[i] == b[k]:
            k += 1
        pi[i] = k

    q = -(-len(b) // len(a))
    k = 0
    for i in range((q + 1) * len(a)):
        ch = a[i % len(a)]
        while k and ch != b[k]:
            k = pi[k - 1]
        if ch == b[k]:
            k += 1
        if k == len(b):
            return i // len(a) + 1
    return -1
